import type { CorpusSection } from '../retriever.js';

export const zhouyiextCorpus: CorpusSection[] = [{"segId":"zhouyi@ext.c.1","text":"䷀乾下，乾上。乾：元，亨，利，貞。初九，濳龍勿用。文言備矣。九二，見龍在田，利見大人。出濳離隱，故曰見龍；處於地上，故曰在田。德施周普，居中不偏。雖非君位，君之德也。初則不彰，三則乾乾，四則或躍，上則過亢。利見大人，唯二、五焉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.2","text":"九三，君子終日乾乾，夕惕若厲，无咎。處下體之極，居上體之下，在不中之位，履重剛之險。上不在天，未可以安其尊也。下不在田，未可以寜其居也。純脩下道，則居上之德廢；純脩上道，則處下之禮曠。故終日乾乾，至于夕惕猶若厲也。居上不驕，在下不憂，因時而惕，不失其幾，雖危而勞，可以无咎。處下卦之極，愈於上九之亢，故竭知力而後免於咎也。乾三以處下卦之上，故免亢龍之悔。坤三以處下卦之上，故免龍戰之災。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.3","text":"九四，或躍在淵，无咎。去下體之極，居上體之下，乾道革之時也。上不在天，下不在田，中不在人，履重剛之險，而无定位所處，斯誠進退无常之時也。近乎尊位，欲進其道，迫乎在下，非躍所及。欲静其居，居非所安。持疑猶豫，未敢決志，用心存公，進不在私，疑以爲慮，不謬於果，故无咎也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.4","text":"九五，飛龍在天，利見大人。不行不躍而在乎天，非飛如何？故曰飛龍也。龍德在天，則大人之路亨也。夫位以德興，德以位叙，以至德而處盛位，萬物之覩，不亦宜乎。上九，亢龍有悔。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.5","text":"用九，見羣龍无首，吉。九，天之德也。能用天德，乃見羣龍之義焉。夫以剛健而居人之首，則物之所不與也。以柔順而爲不正，則佞邪之道也。故乾吉在无首，坤利在永貞。《彖》曰：大哉乾元！萬物資始，乃統天。雲行雨施，品物流形。大明終始，六位時成，時乗六龍以御天。乾道變化，各正性命，天也者，形之名也。健也者，用形者也。夫形也者，物之累也。有天之形而能永保无虧，爲物之首，統之者豈非至健哉？大明乎終始之道，故六位不失其時而成。升降无常，隨時而用，處則乗潛龍，出則乘飛龍，故曰時乗六龍也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.6","text":"乗變化而御大器，静專動直，不失大和，豈非正性命之情者邪？保合大和，乃利貞。不和而剛暴。首出庶物，萬國咸寜。萬國所以寜，各以有君也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.7","text":"《象》曰：天行健，君子以自強不息。“潛龍勿用”，陽在下也；“見龍在田”，德施普也；“終日乾乾”，反復道也；以上言之則不驕，以下言之則不憂，反復皆道也。“或躍在淵”，進无咎也；“飛龍在天”，大人造也；“亢龍有悔”，盈不可乆也；“用九”，天德不可爲首也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.8","text":"《文言》曰：元者，善之長也；亨者，嘉之㑹也；利者，義之和也；貞者，事之幹也。君子體仁足以長人，嘉㑹足以合禮，利物足以和義，貞固足以幹事。君子行此四德者，故曰：“乾：元，亨，利，貞。”","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.9","text":"初九曰“濳龍勿用”，何謂也？子曰：“龍德而隱者也。不易乎丗，不爲世俗所移易也。不成乎名；遯丗无悶，不見是而无悶；樂則行之，憂則違之，確乎其不可拔，‘濳龍’也。”","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.10","text":"九二曰“見龍在田，利見大人”，何謂也？子曰：“龍德而正中者也。庸言之信，庸行之謹；閑邪存其誠，善丗而不伐，德博而化。《易》曰：‘見龍在田，利見大人’，君德也。”","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.11","text":"九三曰“君子終日乾乾，夕惕若厲，无咎”，何謂也？子曰：“君子進德脩業。忠信，所以進德也；脩辭立其誠，所以居業也。知至至之，可與幾也；知終終之，可與存義也。處一體之極，是至也。居一卦之盡，是終也。處事之至而不犯咎，知至者也，故可與成務矣。處終而能全其終，知終者也。夫進物之速者，義不若利；存物之終者，利不及義。故靡不有初，鮮克有終。夫可與存義者，其唯知終者乎。是故居上位而不驕，在下位而不憂。居下體之上，在上體之下，明夫終敝，故不驕也；知夫至至，故不憂也。故乾乾因其時而惕，雖危无咎矣。”惕，怵惕之謂也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.12","text":"處事之極，失時則廢，懈怠則曠，故因其時而惕，雖危无咎。九四曰“或躍在淵，无咎”，何謂也？子曰：“上下无常，非爲邪也；進退无恒，非離羣也。君子進德脩業，欲及時也，故‘无咎’。”","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.13","text":"上九曰“亢龍有悔”，何謂也？子曰：“貴而无位，髙而无民，下无隂也。賢人在下位而无輔，賢人雖在下而當位，不爲之助。是以動而‘有悔’也。”處上卦之極而不當位，故盡陳其闕也。獨立而動，物莫之與矣。乾文言首不論乾，而先說元，下乃曰乾，何也？夫乾者，統行四事者也。君子以自強不息，行此四者，故首不論乾，而下曰乾，元亨利貞。餘爻皆說龍，至於九三，獨以君子爲目，何也？夫易者，象也，象之所生，生於義也。有斯義，然後明之以其物，故以龍叙乾，以馬明坤。隨其事義而取象焉。是故初九、九二龍德皆應其義，故可論龍以明之也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.14","text":"九五曰“飛龍在天，利見大人”，何謂也？子曰：“同聲相應，同氣相求；水流濕，火就燥；雲從龍，風從虎；聖人作而萬物覩；本乎天者親上，本乎地者親下，則各從其類也。”至於九三乾乾夕惕，非龍德也，明以君子當其象矣。統而舉之，乾體皆龍，別而叙之，各隨其義。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.15","text":"“濳龍勿用”，下也；“見龍在田”，時舎也；“終日乾乾”，行事也；“或躍在淵”，自試也；“飛龍在天”，上治也；“亢龍有悔”，窮之災也；乾元“用九”，天下治也。此一章全以人事明之也。九，陽也。陽，剛直之物也。夫能全用剛直，放逺善柔，非天下至理，未之能也。故乾元用九，則天下治也。夫識物之動，則其所以然之理，皆可知也。龍之爲徳，不爲妄者也。潛而勿用，何乎？必窮處於下也。見而在田，必以時之通舎也。以爻爲人，以位爲時，人不妄動，則時皆可知也。文王明夷，則主可知矣。仲尼旅人，則國可知矣。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.16","text":"“潛龍勿用”，陽氣濳藏；“見龍在田”，天下文明；“終日乾乾”，與時偕行；與天時俱不息。“或躍在淵”，乾道乃革；“飛龍在天”，乃位乎天德；“亢龍有悔”，與時偕極；與時運俱終極。乾元“用九”，乃見天則。此一章全說天氣以明之也。九，剛直之物、唯乾體能用之。用純剛以觀天、天則可見矣。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.17","text":"“乾，元”者，始而亨者也；“利，貞”者，性情也。不爲乾元，何能通物之始？不性其情，何能乆行其正？是故始而亨者，必乾元也；利而正者，必性情也。乾始能以美利利天下，不言所利，大矣哉！大哉乾乎，剛健中正，純粹精也；六爻發揮，旁通情也；時乗六龍，以御天也；雲行雨施，天下平也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.18","text":"君子以成德爲行，日可見之行也。“濳”之爲言也，隱而未見，行而未成，是以君子弗用也。君子學以聚之，問以辯之，以君德而處下體，資納於物者也。寛以居之，仁以行之。《易》曰“見龍在田，利見大人”，君德也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.19","text":"九三重剛而不中，上不在天，下不在田，故乾乾因其時而惕，雖危无咎矣。九四重剛而不中，上不在天，下不在田，中不在人，故“或”之。“或”之者，疑之也，故无咎。夫“大人”者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶。先天而天弗違，後天而奉天時。天且弗違，而況於人乎？況於鬼神乎？","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.20","text":"“亢”之爲言也，知進而不知退，知存而不知亡，知得而不知䘮。其唯聖人乎，知進退存亡，而不失其正者，其唯聖人乎！䷁坤下，坤上。坤：元亨，利牝馬之貞。坤，貞之所利，利於牝馬也。馬在下而行者也，而又牝焉，順之至也。至順而後乃亨，故唯利於牝馬之貞。君子有攸往，先迷後得，主利。西南得朋，東北䘮朋，安貞吉。西南，致養之地，與坤同道者也，故曰得朋。東北，反西南者也，故曰喪朋。隂之爲物，必離其黨，之於反類，而後獲安貞吉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.21","text":"《彖》曰：至哉坤元！萬物資生，乃順承天。坤厚載物，德合无疆；含弘光大，品物咸亨。牝馬地類，行地无疆，地之所以得无疆者，以卑順行之故也。乾以龍御天，坤以馬行地。柔順利貞。君子攸行，先迷失道，後順得常。西南得朋，乃與類行；東北䘮朋，乃終有慶。安貞之吉，應地无疆。地也者，形之名也。坤也者，用地者也。夫兩雄必爭，二主必危。有地之形，與剛健爲耦，而能永保无疆，用之者不亦至順乎？若夫行之不以牝馬，利之不以永貞，方而又剛，柔而又圎，求安難矣。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.22","text":"《象》曰：地勢坤，地形不順，其勢順。君子以厚德載物。初六，履霜，堅冰至。始於履霜，至于堅冰，所謂至柔而動也剛。隂之爲道，本於卑弱而後積著者也，故取履霜以明其始。陽之爲物，非基於始以至於著者也，故以出處明之，則以初爲濳。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.23","text":"《象》曰：“履霜堅冰”，隂始凝也；馴致其道，至堅冰也。六二，直方大，不習无不利。居中得正，極於地質，任其自然而物自生，不假脩營而功自成，故不習焉而无不利。《象》曰：六二之動，直以方也；動而直方，任其質也。“不習无不利”，地道光也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.24","text":"六三，含章可貞；或從王事，无成有終。三處下卦之極，而不疑於陽，應斯義者也。不爲事始，湏唱乃應，待命乃發，含美而可正者也，故曰含章可貞也。有事則從，不敢爲首，故曰或從王事也。不爲事主，順命而終，故曰无成有終也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.25","text":"《象》曰：“含章可貞”，以時發也；“或從王事”，知光大也。知慮光大，故不擅其美。六四，括囊，无咎无譽。處隂之卦，以隂居隂，履非中位，无直方之質；不造陽事，无含章之美。括結否閉，賢人乃隱；施愼則可，非泰之道。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.26","text":"《象》曰：“括囊无咎”，愼不害也。六五，黃裳，元吉。黃，中之色也。裳，下之飾也。坤爲臣道，美盡於下。夫體无剛健，而能極物之情，通理者也。以柔順之德，處於盛位，任夫文理者也。垂黃裳以獲元吉，非用武者也。極隂之盛，不至疑陽，以文在中，美之至也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.27","text":"《象》曰：黃裳元吉，文在中也。用黃裳而獲元吉，以文在中也。上六，龍戰于野，其血玄黃。隂之爲道，卑順不盈，乃全其美，盛而不巳，固陽之地，陽所不堪，故戰于野。《象》曰：“龍戰于野”，其道窮也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.28","text":"用六，利永貞。用六之利，利永貞也。《象》曰：用六“永貞”，以大終也。能以永貞大終者也。《文言》曰：坤至柔而動也剛，至静而德方。動之方正，不爲邪也；柔而又圎，消之道也；其德至静，德必方也。後得主而有常，含萬物而化光。坤道其順乎！承天而時行。積善之家，必有餘慶；積不善之家，必有餘殃。臣弑其君，子弑其父，非一朝一夕之故，其所由來者漸矣！由辯之不早辯也。《易》曰：“履霜，堅冰至”，蓋言順也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.29","text":"“直”其正也，“方”其義也。君子敬以直内，義以方外，敬義立而德不孤。“直方大，不習无不利”，則不疑其所行也。隂雖有美，含之以從王事，弗敢成也。地道也，妻道也，臣道也。地道无成而代有終也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.30","text":"天地變化，草木蕃；天地閉，賢人隱。《易》曰：“括囊，无咎无譽。”蓋言謹也。君子黃中通理，正位居體，美在其中，而暢於四支，發於事業，美之至也。隂疑於陽必戰。辯之不早，疑盛乃動，故必戰。爲其嫌於无陽也，爲其嫌於非陽而戰。故稱“龍”焉；猶未離其類也，猶未失其隂類，爲陽所滅。故稱“血”焉。猶與陽戰而相傷，故稱血。夫玄黃者，天地之雜也，天玄而地黃。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.31","text":"䷂震下，坎上。屯：元亨，利貞；剛柔始交，是以屯也。不交則否，故屯乃大亨也。大亨則无險，故利貞。勿用有攸往，往益屯也。利建侯。得主則定。《彖》曰：屯，剛柔始交而難生；動乎險中，大亨貞。始於險難，至於大亨，而後全正，故曰：“屯，元亨，利貞。”雷雨之動滿盈，雷雨之動，乃得滿盈，皆剛柔始交之所爲。天造草昧；宜建侯而不寧。屯體不寧，故利建侯也。屯者，天地造始之時也。造物之始，始於冥昧，故曰草昧也。處造始之時，所宜之善，莫善建侯也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.32","text":"《象》曰：雲雷，屯；君子以經綸。君子經綸之時。初九，磐桓，利居貞，利建侯。處屯之初，動則難生，不可以進，故磐桓也。處此時也，其利安在？不唯居貞建侯乎？夫息亂以靜，守靜以侯，安民在正，弘正在謙。屯難之丗，隂求於陽，弱求於強，民思其主之時也。初處其首，而又下焉，爻備斯義，宜其得民也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.33","text":"《象》曰：雖磐桓，志行正也；不可以進，故磐恒也；非爲宴安棄成務也，故雖磐桓，志行正也。以貴下賤，大得民也。陽貴而隂賤也。六二，屯如邅如。乗馬班如，匪宼㛰媾；女子貞不字，十年乃字。志在乎五，不從於初，屯難之時，正道未行，與初相近而不相得，困於侵害，故屯邅也。時方屯難，正道未通，渉逺而行，難可以進，故曰乗馬班如也。宼謂初也。无初之難，則與五㛰矣，故曰匪宼㛰媾也。志在於五，不從於初，故曰女子貞不字也。屯難之丗，勢不過十年者也，十年則反常，反常則本志斯獲矣，故曰十年乃字。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.34","text":"《象》曰：六二之難，乗剛也；十年乃字，反常也。六三，即鹿无虞，惟入于林中；君子幾，不如舎，往吝。三旣近五而无宼難，四雖比五，其志在初，不妨巳路，可以進而无屯邅也。見路之易，不揆其志，五應在二，往必不納，何異无虞以從禽乎？雖見其禽而无其虞，徒入于林中，其可獲乎？幾，辭也。夫君子之動，豈取恨辱哉，故不如舎，往吝，窮也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.35","text":"《象》曰：“即鹿无虞”，以從禽也；“君子舎之，往吝”，窮也。六四，乗馬班如，求㛰媾；往吉，无不利。二雖比初，執貞不從，不害己志者也。求與合好，往必見納矣，故曰往吉无不利。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.36","text":"《象》曰：求而往，明也。見彼之情狀也。九五，屯其膏。小，貞吉；大，貞凶。處屯難之時，居尊位之上，不能恢弘博施，无物不與，拯濟微滯，亨于羣小，而繫應在二，屯難其膏，非能光其施者也。固志同好，不容他間，小貞之吉，大貞之凶。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.37","text":"《象》曰：“屯其膏”，施未光也。上六，乗馬班如，泣血漣如。處險難之極，下无應援，進无所適，雖比於五，五屯其膏，不與相得，居不獲安，行无所適，窮困闉厄，无所委仰，故泣血漣如。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.38","text":"《象》曰：“泣血漣如”，何可長也？䷃坎下，艮上。蒙：亨。匪我求童蒙，童蒙求我；初筮告，再三瀆，瀆則不告。筮者，決疑之物也。童蒙之來求我，欲決所惑也。決之不一，不知所從，則復惑也。故初筮則告，再三則瀆。瀆，蒙也。能爲初筮，其唯二乎？以剛處中，能斷夫疑者也。利貞。蒙之所利，乃利正也。夫明莫若聖，昧莫若蒙，蒙以養正，乃聖功也。然則養正以明，失其道矣。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.39","text":"《彖》曰：蒙，山下有險，險而止蒙。退則困險，進則閡山，不知所適，蒙之義也。“蒙，亨”，以亨行時中也。時之所願，唯願亨也。以亨行之，得時中也。“匪我求童蒙，童蒙求我”，志應也。我，謂非童蒙者也。非童蒙者，即陽也。凡不識者求問識者，識者不求所告；闇者求明，明者不諮於闇。故蒙之爲義，匪我求童蒙，童蒙求我也。童蒙之來求我，志應故也。“初筮告”，以剛中也；謂二也。二爲衆隂之主也。无剛決中，何由得初筮之告乎。“再三瀆，瀆則不告”，瀆蒙也。蒙以養正，聖功也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.40","text":"《象》曰：山下出泉，蒙；山下出泉，未知所適，蒙之象也。君子以果行育德。果行者，初筮之義也；育德者，養正之功也。初六，發蒙，利用刑人，用說桎梏；以往吝。處蒙之初，二照其上，故蒙發也。蒙發疑明，刑說當也。以往吝，刑不可長。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.41","text":"《象》曰：利用刑人，以正法也。刑人之道，道所惡也。以正法制，故刑人也。九二，包蒙，吉，納婦吉，子克家。以剛居中，童蒙所歸，包而不距，則逺近咸至，故包蒙吉也。婦者，配己而成德者也。體陽而能包蒙，以剛而能居中，以此納配，物莫不應，故納婦吉也。處于卦内，以剛接柔，親而得中，能幹其任，施之於子，克家之義。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.42","text":"《象》曰：“子克家”，剛柔接也。六三，勿用取女，見金夫，不有躬，无攸利。童蒙之時，隂求於陽，晦求於明，各求發其昧者也。六三在下卦之上，上九在上卦之上，男女之義也。上不求三，而三求上，女先求男者也。女之爲體，正行以待命者也。見剛夫而求之，故曰不有躬也。施之於女，行在不順，故勿用取女，而无攸利。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.43","text":"《象》曰：“勿用取女”，行不順也。六四，困蒙，吝。獨逺於陽，處兩隂之中，闇莫之發，故曰困蒙也。困於蒙昧，不能比賢以發其志，亦以鄙矣，故曰吝也。《象》曰：“困蒙之吝”，獨逺實也。陽稱實也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.44","text":"六五，童蒙，吉。以夫隂質居於尊位，不自任察而委於二，付物以能，不勞聦明，功斯克矣，故曰童蒙吉。《象》曰：“童蒙之吉”，順以巽也。委物以能，不先不爲，順以巽也。上九，擊蒙；不利爲宼，利禦宼。處蒙之終，以剛居上，能擊去童蒙，以發其昧者也，故曰擊蒙也。童蒙願發，而己能擊去之，合上下之願，故莫不順也。爲之扞禦，則物咸附之，若欲取之，則物咸叛矣，故不利爲宼，利禦宼也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.45","text":"《象》曰：“利用禦宼”，上下順也。䷄乾下，坎上。需：有孚，光亨，貞吉，利渉大川。《彖》曰：“需”，須也；險在前也，剛健而不䧟，其義不困窮矣。“需，有孚，光亨，貞吉”，位乎天位，以正中也。謂五也。位乎天位，用其中正，以此待物，需道畢矣。故光亨貞吉。“利渉大川”，往有功也。乾德獲進，往輒亨也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.46","text":"《象》曰：雲上於天，需；君子以飲食宴樂。童蒙已發，盛德光亨。飲食宴樂，其在兹乎。初九，需于郊，利用恒，无咎。居需之時、最逺於難。能抑其進。以逺險待時、雖不應幾、可以保常也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.47","text":"《象》曰：“需于郊”，不犯難行也；“利用恒，无咎”，未失常也。九二，需于沙，小有言；終吉。轉近於難，故曰需于沙也；不至致宼，故曰小有言也。近不逼難，逺不後時，履健居中，以待其㑹，雖小有言，以吉終也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.48","text":"《象》曰：“需于沙”，衍在中也。雖小有言，以吉終也。九三，需于泥，致宼至。以剛逼難，欲進其道，所以招宼。而致敵也，猶有須焉，不䧟其剛。宼之來也，自我所招，敬愼防備，可以不敗。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.49","text":"《象》曰：“需于泥”，災在外也；自我致宼，敬愼不敗也。六四，需于血，出自穴。凡稱血者，隂陽相傷者也。隂陽相近而不相得，陽欲進而隂塞之，則相害也。穴者，隂之路也。處坎之始，居穴者也。九三剛進，四不能距，見侵則辟，順以聽命者也。故曰需于血，出自穴也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.50","text":"《象》曰：“需于血”，順以聽也。九五，需于酒食，貞吉。需之所須，以待達也。已得天位，暢其中正，无所復須，故酒食而巳，獲貞吉也。《象》曰：“酒食貞吉”，以中正也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.51","text":"上六，入于穴，有不速之客三人來；敬之，終吉。六四所以出自穴者，以不與三相得而塞其路，不辟則害，故不得不出自穴而辟之也。至於上六，處卦之終，非塞路者也。與三爲應，三來之已，乃爲已援，故无畏害之辟，而乃有入穴之固也。三陽所以不敢進者，須難之終也。難終則至，不待召也。已居難終，故自來也。處无位之地，以一隂而爲三陽之主，故必敬之而後終吉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.52","text":"《象》曰：“不速之客來，敬之終吉”，雖不當位，未大失也。處无位之地，不當位者也。敬之則得終吉，故雖不當位，未大失也。䷅坎下，乾上。訟：有孚窒惕，中吉；窒，謂窒塞也。皆惕然後可以獲中吉。終凶，利見大人，不利渉大川。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.53","text":"《彖》曰：訟，上剛下險，險而健，訟。“訟：有孚窒惕，中吉”，剛來而得中也。“終凶”，訟不可成也。“利見大人”，尚中正也。“不利渉大川”，入于淵也。凡不和而訟，无施而可，渉難特甚焉。唯有信而見塞懼者，乃可以得吉也。猶復不可終，中乃吉也。不閉其源，使訟不至，雖每不枉，而訟至終竟，此亦凶矣。故雖復有信而見塞懼，猶不可以爲終也。故曰訟，有孚，窒惕，中吉，終凶也。无善聽者，雖有其實，何由得明，而令有信塞懼者得其中吉？必有善聽之主焉，其在二乎？以剛而來，正夫羣小，斷不失中，應斯任也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.54","text":"《象》曰：天與水違行，訟；君子以作事謀始。聽訟，吾猶人也，必也使无訟乎！无訟在於謀始，謀始在於作制。契之不明，訟之所以生也。物有其分，職不相濫，爭何由興？訟之所以起，契之過也。故有德司契而不責於人。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.55","text":"初六，不永所事；小有言，終吉。處訟之始，訟不可終，故不永所事，然後乃吉。凡陽唱而隂和，隂非先唱者也。四召而應，見犯乃訟。處訟之始，不爲訟先，雖不能不訟而了，訟必辯明也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.56","text":"《象》曰：“不永所事”，訟不可長也；雖“小有言”，其辯明也。九二，不克訟，歸而逋，其邑人三百户，无眚。以剛處訟，不能下物，自下訟上，冝其不克。若能以懼，歸竄其邑，乃可以免災。邑過三百，非爲竄也，竄而據強，災未免也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.57","text":"《象》曰：“不克訟”，歸逋竄也；自下訟上，患至掇也。六三，食舊德，貞厲，終吉；或從王事，无成。體夫柔弱，以順於上，不爲九二，自下訟上，不見侵奪，保全其有，故得食其舊德而不失也。居爭訟之時，處兩剛之間，而皆近不相得，故曰貞厲。柔體不爭，繫應在上，衆莫能傾，故曰終吉。上壯爭勝，難可忤也，故或從王事，不敢成也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.58","text":"《象》曰：食舊德，從上吉也。九四，不克訟；初辯明也。復即命，渝，安貞吉。處上訟下，可以改變者也，故其咎不大。若能反從本理，變前之命，安貞不犯，不失其道，爲仁由己，故吉從之。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.59","text":"《象》曰：復即命，渝，安貞不失也。九五，訟，元吉。處得尊位，爲訟之主，用其中正，以㫁枉直，中則不過，正則不邪，剛无所溺，公无所偏，故訟元吉。《象》曰：“訟，元吉”，以中正也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.60","text":"上九，或錫之鞶帶，終朝三褫之。處訟之極，以剛居上，訟而得勝者也。以訟受錫，榮何可保？故終朝之間，褫帶者三也。《象》曰：以訟受服，亦不足敬也。䷆坎下，坤上。師：貞，丈人吉，无咎。丈人，嚴莊之稱也。爲師之正，丈人乃吉也。典役動衆，无功，罪也，故吉乃无咎也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.61","text":"《彖》曰：師，衆也；貞，正也。能以衆正，可以王矣。剛中而應，行險而順，以此毒天下，而民從之，吉又何咎矣！毒，猶役也。《象》曰：地中有水，師；君子以容民畜衆。初六，師出以律，否臧凶。爲師之始，齊師者也。齊衆以律，失侓則散，故師出以律。律不可失，失律而臧，何異於否？失令有功，法所不赦。故師出不以律，否臧皆凶。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.62","text":"《象》曰：“師出以律”，失律凶也。九二，在師中，吉，无咎；王三錫命。以剛居中，而應於上，在師而得中者也。承上之寵，爲師之主，任大役重，无功則凶，故吉乃无咎也。行師得吉，莫善懷邦，邦懷衆服，錫莫重焉，故乃得成命。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.63","text":"《象》曰：“在師中吉”，承天寵也；“王三錫命”，懷萬邦也。六三，師或輿尸，凶。以隂處陽，以柔乗剛，進則无應，退无所守，以此用師，冝獲輿尸之凶。《象》曰：“師或輿尸”，大无功也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.64","text":"六四，師左次，无咎。得位而无應，无應不可以行，得位則可以處，故左次之而无咎也。行師之法，欲右背髙，故左次之。《象》曰：“左次无咎”，未失常也。雖不能有獲，足以不失其常也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.65","text":"六五，田有禽，利執言，无咎；長子帥師，弟子輿尸，貞凶。處師之時，柔得尊位，隂不先唱，柔不犯物，犯而後應，往必得直，故田有禽也。物先犯己，故可以執言而无咎也。柔非軍帥，隂非剛武，故不躬行，必以授也。授不得主，則衆不從，故長子帥師可也。弟子之凶，固其冝也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.66","text":"《象》曰：“長子帥師”，以中行也；“弟子輿尸”，使不當也。上六，大君有命，開國承家，小人勿用。處師之極，師之終也。大君之命，不失功也。開國承家，以寧邦也。小人勿用，非其道也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.67","text":"《象》曰：“大君有命”，以正功也；“小人勿用”，必亂邦也。䷇坤下，坎上。比：吉。原筮，元永貞，无咎。不寧方來，後夫凶。《彖》曰：比，吉也；比，輔也，下順從也。“原筮，元永貞，无咎”，以剛中也。處比之時，將原筮以求无咎，其唯元永貞乎？夫羣黨相比，而不以元永貞，則凶邪之道也。若不遇其主，則雖永貞而猶未足免於咎也。使永貞而无咎者，其唯九五乎？“不寧方來”，上下應也。上下无陽以分其民，五獨處尊，莫不歸之。上下應之，旣親且安，安則不安者託焉，故不寧方所以來，上下應故也。夫无者求有，有者不求所與；危者求安，安者不求所保。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.68","text":"火有其炎，寒者附之，故己苟安焉，則不寧方來矣。“後夫凶”，其道窮也。將合和親，而獨在後，親成則誅，是以凶也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.69","text":"《象》曰：地上有水，比；先王以建萬國，親諸侯。萬國以比建，諸侯以比親。初六，有孚比之，无咎；有孚盈缶，終來有它，吉。處比之始，爲比之首者也。夫以不信爲比之首，則禍莫大焉。故必有孚盈缶，然後乃得免比之咎，故曰有孚比之，无咎也。處比之首，應不在一，心无私吝，則莫不比之。著信立誠，盈溢乎質素之器，則物終來无衰竭也。親乎。天下，著信盈缶，應者豈一道而來？故必有它吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.70","text":"《象》曰：比之初六，有它吉也。六二，比之自内，貞吉。處比之時，居中得位，而繫應在五，不能來它，故得其自内貞吉而巳。《象》曰：“比之自内”，不自失也。六三，比之匪人。四自外比，二爲五貞，近不相得，遠則无應，所與比者，皆非己親，故曰比之匪人。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.71","text":"《象》曰：“比之匪人”，不亦傷乎！六四，外比之，貞吉。外比於五，履得其位，比不失賢，處不失位，故貞吉也。《象》曰：外比於賢，以從上也。九五，顯比；王用三驅，失前禽，邑人不誡，吉。爲比之主，而有應在二，顯比者也。比而顯之，則所親者狹矣。夫无私於物，唯賢是與，則去之與來，皆无失也。夫三驅之禮，禽逆來趣己則舎之，背己而走則射之，愛於來而惡於去也，故其所施，常失前禽也。以顯比而居王位，用三驅之道者也，故曰王用三驅，失前禽也。用其中正，征討有常，伐不加邑，動必討叛，邑人无虞，故不誡也。雖不得乎大人之吉，是顯比之吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.72","text":"《象》曰：“顯比”之吉，位正中也；舎逆取順，失前禽也；邑人不誡，上使中也。上六，比之无首，凶。无首，後也。處卦之終，是後夫也。親道已成，无所與終，爲時所棄，宜其凶也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.73","text":"《彖》曰：“小畜”，柔得位而上下應之，曰小畜。謂六四也。成卦之義，在此爻也。體无二隂以分其應，故上下應之也。旣得其位，而上下應之，三不能陵，小畜之義。健而巽，剛中而志行，乃亨。“密雲不雨”，尚往也；“自我西郊”，施未行也。小畜之勢，足作密雲，乃自我西郊，未足以爲雨也。何由知未能爲雨？夫能爲雨者，陽上薄隂，隂能固之，然後烝而爲雨。今不能制初九之復道，固九二之牽復，九三更以不能復爲劣也。下方尚徃，施豈得行？故密雲而不能爲雨，尚往故也。何以明之？夫隂能固之，然後乃雨乎。上九獨能固九三之路，故九三不可以進而輿說輻也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.74","text":"《象》曰：“比之无首”，无所終也。䷈乾下，巽上。小畜：亨；不能畜大止健，剛志故行，是以亨。密雲不雨，自我西郊。能固其路而安於上，故得旣雨旣處。若四、五皆能若上九之善畜，則能雨明矣。故舉一卦而論之，能爲小畜密雲而已。隂苟不足以固陽，則雖復至盛，密雲自我西郊，故不能雨也。雨之未下、即施之未行也。彖全論一卦之體、故曰密雲不雨。象各言一爻之德、故曰旣雨旣處也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.75","text":"《象》曰：風行天上，“小畜”；君子以懿文德。未能行其施者，故可以懿文德而已。初九，復自道，何其咎？吉。處乾之始，以升巽初，四爲巳應，不距巳者也。以陽升隂，復自其道，順而无違，何所犯咎？得義之吉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.76","text":"《象》曰：“復自道”，其義吉也。九二，牽復，吉。處乾之中，以升巽五，五非畜極，非固巳者也。雖不能若隂之不違，可牽以獲復，是以吉也。《象》曰：牽復在中，亦不自失也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.77","text":"九三，輿說輻，夫妻反目。上爲畜盛，不可牽征，以斯而進，故必說輻也。巳爲陽極，上爲隂長，畜於隂長，不能自復，方之夫妻，反目之義也。《象》曰：夫妻反目，不能正室也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.78","text":"六四，有孚；血去惕出，无咎。夫言血者，陽犯隂也。四乗於三，近不相得，三務於進，而己隔之，將懼侵克者也。上亦惡三，而能制焉，志與上合，共同斯誠，三雖逼己，而不能犯，故得血去懼除，保无咎也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.79","text":"《象》曰：“有孚惕出”，上合志也。九五，有孚攣如，富以其鄰。處得尊位，不疑於二，來而不距，二牽己攣，不爲專固，有孚攣如之謂也。以陽居陽，處實者也。居盛處實而不專固，富以其鄰者也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.80","text":"《象》曰：“有孚攣如”，不獨富也。上九，旣雨旣處，尚德載；婦貞厲，月幾望；君子征凶。處小畜之極，能畜者也。陽不獲亨，故旣雨也。剛不能侵，故旣處也。體巽處上，剛不敢犯，尚德者也。爲隂之長，能畜剛健，德積載者也。婦制其夫，臣制其君，雖貞近危，故曰婦貞厲也。隂之盈盛，莫盛於此，故曰月幾望也。滿而又進，必失其道，隂疑於陽，必見戰伐，雖復君子，以征必凶，故曰君子征凶。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.81","text":"《象》曰：“旣雨旣處”，德積載也；“君子征凶”，有所疑也。夫處下可以征而无咎者，唯泰也則然。坤本體下，又順而弱，不能敵剛，故可以全其類，征而吉也。自此以徃，則其進各有難矣。夫巽雖不能若艮之善畜，猶不肯爲坤之順從也，故可得少進，不可盡陵也。是以初九、九二，其復則可，至於九三，則輿說輻也。夫大畜者，畜之極也。畜而不巳，畜極則通，是以其畜之盛在於四五，至于上九，道乃大行。小畜積極而後乃能畜，是以四五可以進，而上九說征之輻。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.82","text":"䷉兊下，乾上。履：虎尾，不咥人，亨。《彖》曰：“履”，柔履剛也。說而應乎乾，是以“履虎尾，不咥人，亨”。凡彖者，言乎一卦之所以爲主也。成卦之體，在六三也。履虎尾者，言其危也。三爲履主，以柔履剛，履危者也。履虎尾而不見咥者，以其說而應乎乾也。乾，剛正之德者也。不以說行夫佞邪，而以說應乎乾，冝其履虎尾不見咥而亨。剛中正，履帝位而不疚，光明也。言五之德。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.83","text":"《象》曰：上天下澤，“履”；君子以辯上下，定民志。初九，素履，徃，无咎。處履之初，爲履之始，履道惡華，故素乃无咎。處履以素，何往不從？必獨行其願，物无犯也。《象》曰：“素履之徃”，獨行願也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.84","text":"九二，履道坦坦，幽人貞吉。履道尚謙，不喜處盈，務在致誠，惡夫外飾者也。而二以陽處隂，履於謙也。居内履中，隱顯同也。履道之美，於斯爲盛，故履道坦坦，无險厄也。在幽而貞，宜其吉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.85","text":"《象》曰：“幽人貞吉”，中不自亂也。六三，眇能視，跛能履，履虎尾咥人，凶；武人爲于大君。居履之時，以陽處陽，猶曰不謙，而況以隂居陽，以柔乗剛者乎？故以此爲明，眇目者也；以此爲行，跛足者也；以此履危，見咥者也。志在剛健，不脩所履，欲以陵武於人，爲于大君，行未能免於凶，而志存于王，頑之甚也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.86","text":"《象》曰：“眇能視”，不足以有明也；“跛能履”，不足以與行也；“咥人之凶”，位不當也；“武人爲于大君”，志剛也。九四，履虎尾，愬愬，終吉。逼近至尊。以陽承陽。處多懼之地。故曰履虎尾，愬愬也。然以陽居隂。以謙爲本。雖處危懼。終獲其志。故終吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.87","text":"《象》曰：“愬愬終吉”，志行也。九五，夬履，貞厲。得位處尊，以剛決正，故曰：夬履，貞厲也。履道惡盈，而五處實，是以危。《象》曰：“夬履貞厲”，位正當也。上九，視履考祥，其旋元吉。禍福之祥，生乎所履。處履之極，履道成矣，故可視履而考祥也。居極應說，髙而不危，是其旋也。履道大成，故元吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.88","text":"《象》曰：元吉在上，大有慶也。周易卷第一經三千二百五十五字，注五千九百四十四字。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.89","text":"䷊乾下，坤上。泰：小往大來，吉亨。《彖》曰：泰，小往大來，吉亨。則是天地交而萬物通也，上下交而其志同也。内陽而外隂，内健而外順，内君子而外小人，君子道長，小人道消也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.90","text":"《象》曰：天地交泰，后以財成天地之道，輔相天地之冝，以左右民。泰者，物大通之時也。上下大通，則物失其節，故財成而輔相，以左右民也。𥘉九，拔茅茹，以其彚，征吉。茅之爲物，拔其根而相牽引者也。茹，相牽引之貌也。三陽同志，俱志在外；𥘉爲類首，巳舉則從，若茅茹也。上順而應，不爲違距，進皆得志，故以其類征吉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.91","text":"《象》曰：拔茅征吉，志在外也。九二，包荒，用馮河，不遐遺，朋亡，得尚于中行。體健居中而用乎泰，能包含荒穢，受納馮河者也。用心弘大，无所遐棄，故曰不遐遺也。无私无偏，存乎光大，故曰朋亡也。如此乃可以得尚于中行。尚，猶配也。中行，謂五。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.92","text":"《象》曰：包荒，得尚于中行，以光大也。九三，无平不陂，无往不復，艱貞无咎。勿恤其孚，于食有福。乾本上也，坤本下也，而得泰者，降與升也。而三處天地之際，將復其所處。復其所處，則上守其尊，下守其卑，是故无往而不復也，无平而不陂也。處天地之將閉，平路之將陂，時將大變，丗將大革，而居不失其正，動不失其應，艱而能貞，不失其義，故无咎也。信義誠著，故不恤其孚而自明也。故曰勿恤其孚，于食有福也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.93","text":"《象》曰：无往不復，天地際也。天地將各分復之際。六四，翩翩，不富以其鄰，不戒以孚。乾樂上復，坤樂下復。四處坤首，不固所居，見命則退，故曰翩翩也。坤爻皆樂下，己退則從，故不待富。而用其鄰也。莫不與己同其志願，故不待戒而自孚也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.94","text":"《象》曰：翩翩不富，皆失實也。不戒以孚，中心願也。六五，帝乙歸妹，以祉元吉。婦人謂嫁曰歸。泰者，隂陽交通之時也。女處尊位，履中居順，降身應二，感以相與，用中行願，不失其禮。帝乙歸妹，誠合斯義。履順居中，行願以祉，盡夫隂陽交配之冝，故元吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.95","text":"《象》曰：以祉元吉，中以行願也。上六，城復于隍，勿用師，自邑告命，貞吝。居泰上極，各反所應，泰道將滅，上下不交，卑不上承，尊不下施，是故城復于隍，卑道崩也。勿用師，不煩攻也。自邑告命，貞吝。否道巳成，命不行也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.96","text":"《象》曰：城復于隍，其命亂也。䷋坤下，乾上。否之匪人，不利，君子貞，大往小來。《彖》曰：否之匪人，不利，君子貞，大往小來。則是天地不交而萬物不通也，上下不交而天下无邦也。内隂而外陽，内柔而外剛，内小人而外君子，小人道長，君子道消也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.97","text":"《象》曰：天地不交，否。君子以儉德辟難，不可榮以禄。初六，拔茅茹以其彚，貞吉，亨。居否之初，處順之始，爲類之首者也。順非健也，何可以征？居否之時，動則入邪，三隂同道，皆不可進，故茅茹以類，貞而不諂，則吉亨。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.98","text":"《象》曰：拔茅貞吉，志在君也。志在於君，故不苟進。六二，包承，小人吉。大人否，亨。居否之丗，而得其位，用其至順，包承於上，小人路通，内柔外剛，大人否之，其道乃亨。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.99","text":"《象》曰：大人否亨，不亂羣也。六三，包羞。俱用小道以承其上、而位不當、所以包羞也。象曰：包羞，位不當也。九四，有命无咎，疇離祉。夫處否而不可以有命者，以所應者小人也；有命於小人，則消君子之道者也。今初志在君，處乎窮下，故可以有命无咎而疇麗福也。疇，謂初也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.100","text":"《象》曰：有命无咎，志行也。九五，休否，大人吉。其亡其亡，繫于苞桑。居尊當位，能休否道者也。施否於小人，否之休也。唯大人而後能然，故曰大人吉也。處君子道消之時，己居尊位，何可以安？故心存將危，乃得固也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.101","text":"《象》曰：大人之吉，位正當也。上九，傾否，先否後喜。先傾後通，故後喜也。始以傾爲否，後得通乃喜。《象》曰：否終則傾，何可長也。䷌離下，乾上。同人于野，亨，利渉大川，利君子貞。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.102","text":"《彖》曰：同人，柔得位得中而應乎乾，曰同人。二爲同人之主。同人曰：同人于野，亨，利渉大川，乾行也。所以乃能同人于野，亨，利渉大川，非二之所能也，是乾之所行，故特曰同人曰。文明以健，中正而應，君子正也。行健不以武，而以文明用之；相應不以邪，而以中正應之，君子正也，故曰利君子貞。唯君子爲能通天下之志。君子以文明爲德。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.103","text":"《象》曰：天與火，同人。天體於上而火炎上，同人之義也。君子以類族辨物。君子小人，各得所同。初九，同人于門，无咎。居同人之始，爲同人之首者也。无應於上，心无𠈃吝，通夫大同，出門皆同，故曰同人于門也。出門同人，誰與爲咎？","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.104","text":"《象》曰：出門同人，又誰咎也？六二，同人于宗，吝。應在乎五，唯同於主，過主則否，用心褊狹，鄙吝之道。《象》曰：同人于宗，吝道也。九三，伏戎于莽，升其髙陵，三歳不興。居同人之際，履下卦之極，不能包弘上下，通失大同，物黨相分，欲乖其道，貪於所比，據上之應，其敵剛健，非力所當，故伏戎于莽，不敢顯亢也。升其髙陵，望不敢進。量斯勢也，三歳不能興者也。三歳不能興，則五道亦以成矣，安所行焉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.105","text":"《象》曰：伏戎于莽，敵剛也。三歳不興，安行也。安，辭也。九四，乗其墉，弗克攻，吉。處上攻下，力能乗墉者也。履非其位，以與人爭，二自五應，三非犯己，攻三求二，尤而效之，違義傷理，衆所不與，故雖乗墉而不克也。不克則反，反則得吉也。不克乃反，其所以得吉，困而反則者也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.106","text":"《象》曰：乗其墉，義弗克也。其吉，則困而反則也。九五，同人，先號咷，而後笑，大師克相遇。彖曰：柔得位得中，而應乎乾，曰同人。然則體柔居中，衆之所與；執剛用直，衆所未從。故近隔乎二剛，未獲厥志，是以先號咷也。居中處尊，戰必克勝，故後笑也。不能使物自歸，而用其強直，故必須大師克之，然後相遇也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.107","text":"《象》曰：同人之先，以中直也。大師相遇，言相克也。上九，同人于郊，无悔。郊者，外之極也。處同人之時，最在於外，不獲同志，而逺於内爭，故雖无悔吝，亦未得其志。《象》曰：“同人于郊”，志未得也。凡處同人而不泰焉，則必用師矣。不能大通，則各私其黨而求利焉。楚人亡弓，不能亡楚；愛國愈甚，益爲它災，是以同人不弘，剛健之爻，皆至用師也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.108","text":"䷍乾下，離上。大有：元亨。不大通，何由得大有乎？大有，則必元亨矣。《彖》曰：“大有”，柔得尊位大中，而上下應之，曰大有。處尊以柔，居中以大，體无二隂，以分其應，上下應之，靡所不納，大有之義也。其德剛健而文明，應乎天而時行，是以元亨。德應於天，則行不失時矣。剛健不滯，文明不犯，應天則大，時行无違，是以元亨。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.109","text":"《象》曰：火在天上，“大有”；君子以遏惡揚善，順天休命。大有，包容之象也。故遏惡揚善，成物之美，順夫天德，休物之命。初九，无交害，匪咎，艱則无咎。以夫剛健爲大有之始，不能履中，滿而不溢，術斯以往，後害必至，其欲匪咎，艱則无咎也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.110","text":"《象》曰：《大有》初九，无交害也。九二，大車以載，任重而不危。有攸往，无咎。健不違中，爲五所任；任重不危，致逺不泥。故可以往而无咎也。《象》曰：大車以載，積中不敗也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.111","text":"九三，公用亨于天子，小人弗克。處大有之時，居下體之極，乗剛健之上，而履得其位，與五同功，威權之盛，莫此過焉。公用斯位，乃得通乎天子之道也。小人不克，害可待也。《象》曰：公用亨于天子，小人害也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.112","text":"九四，匪其彭，无咎。旣失其位，而上近至尊之威，下比分權之臣，其爲懼也，可謂危矣。唯夫有聖知者，乃能免斯咎也。三雖至盛，五不可舎，能辯斯数，專心承五，常匪其旁，則无咎矣。旁，謂三也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.113","text":"《象》曰：“匪其彭无咎”，明辯晢也。明，猶才也。六五，厥孚交如，威如，吉。居尊以柔，處大以中，无私於物，上下應之，信以發志，故其孚交如也。夫不私於物，物亦公焉；不疑於物，物亦誠焉。旣公且信，何難何備？不言而教行，何爲而不威？如？爲大有之主，而不以此道，吉可得乎？","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.114","text":"《象》曰：“厥孚交如”，信以發志也。威如之吉，易而无備也。上九，自天祐之，吉无不利。大有，豐富之丗也。處大有之上，而不累於位，志尚乎賢者也。餘爻皆乗剛，而已，獨乗柔，順也。五爲信德，而巳履焉，履信之謂也。雖不能體柔，而以剛乗柔，思順之義也。居豐有之丗，而不以物累其心，髙尚其志，尚賢者也。爻有三德，盡夫助道，故繫辭具焉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.115","text":"《象》曰：《大有》上吉，自天祐也。䷎艮下，坤上。謙，亨，君子有終。《彖》曰：謙，亨，天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可踰，君子之終也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.116","text":"《象》曰：地中有山，謙，君子以裒多益寡，稱物平施。多者用謙以爲裒，少者用謙以爲益，隨物而與，施不失平也。初六，謙謙君子，用渉大川，吉。處謙之下，謙之謙者也。能體謙謙，其唯君子。用渉大難，物无害也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.117","text":"《象》曰：“謙謙君子”，卑以自牧也。牧，養也。六二，鳴謙，貞吉。鳴者，聲名聞之謂也。得位居中，謙而正焉。《象》曰：“鳴謙貞吉”，中心得也。九三，勞謙，君子有終，吉。處下體之極，履得其位，上下无陽以分其民，衆隂所宗，尊莫先焉。居謙之丗，何可安尊？上承下接，勞謙匪懈，是以吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.118","text":"《象》曰：勞謙君子，萬民服也。六四，无不利，撝謙。處三之上而用謙焉，則是自上下下之義也。承五而用謙順，則是上行之道也。盡乎奉上下下之道，故无不利。指撝皆謙，不違則也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.119","text":"《象》曰：无不利，撝謙，不違則也。六五，不富，以其鄰利用侵伐，无不利。居於尊位，用謙與順，故能不富而用其鄰也。以謙順而侵伐，所伐皆驕逆也。《象》曰：“利用侵伐”，征不服也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.120","text":"上六，鳴謙，利用行師，征邑國。最處於外，不與内政，故有名而已，志功未得也。處外而履謙順，可以征邑國而已。《象》曰：“鳴謙”，志未得也。“可用行師”，征邑國也。夫吉凶悔吝，生乎動者也。動之所起，興於利者也。故飲食必有訟，訟必有衆起。未有居衆人之所惡，而爲動者所害，處不競之地，而爲爭者所奪。是以六爻雖有失位，无應乗剛，而皆无凶咎悔吝者，以謙爲主也。謙尊而光，卑而不可踰，信矣哉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.121","text":"䷏坤下震上。豫：利建侯行師。《彖》曰：豫，剛應而志行，順以動，豫。豫，順以動，故天地如之，而況建侯行師乎？天地以順動，故日月不過，而四時不忒；聖人以順動，則刑罰清而民服，豫之時義大矣哉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.122","text":"《象》曰：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。初六，鳴豫，凶。處豫之初，而特得志於上，樂過則淫，志窮則凶，豫何可鳴？《象》曰：初六“鳴豫”，志窮凶也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.123","text":"六二，介于石，不終日，貞吉。處豫之時，得位履中，安夫貞正，不求苟豫者也。順不苟從，豫不違中，是以上交不諂，下交不瀆。明禍福之所生，故不苟說；辯必然之理，故不改其操。介如石焉，不終日，明矣。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.124","text":"《象》曰：不終日貞吉，以中正也。六三，盱豫悔，遟有悔。居下體之極，處兩卦之際，履非其位，承動豫之主。若其睢盱而豫，悔亦主焉。遟而不從，豫之所疾。位非所據，而以從豫，進退，離悔，冝其然矣。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.125","text":"象曰：“盱豫有悔”，位不當也。九四，由豫，大有得，勿疑，朋盍簪。處豫之時，居動之始，獨體陽爻，衆隂所從，莫不由之以得其豫，故曰由豫，大有得也。夫不信於物，物亦疑焉，故勿疑則朋合疾也。盍，合也。簪，疾也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.126","text":"《象》曰：“由豫大有得”，志大行也。六五，貞疾，恒不死。四以剛動。爲豫之主。專權執制。非己所乗。故不敢與四爭權。而又居中處尊。未可得亡。是以必常至于貞疾。恒不死而巳。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.127","text":"《象》曰：六五“貞疾”，乗剛也；“恒不死”，中未亡也。上六，冥豫成，有渝无咎。處動豫之極，極豫盡樂，故至于㝠豫成也。過豫不已，何可長乎？故必渝變，然後无咎。《象》曰：“冥豫”在上，何可長也？","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.128","text":"䷐震下，兊上。隨，元亨利貞，无咎。《彖》曰：隨，剛來而下柔，動而說。隨，大亨，貞无咎，而天下隨時，隨時之義大矣哉！震剛而兊柔也。以剛下柔，動而之說，乃得隨也。爲隨而不大通，逆於時也；相隨而不爲利，正，災之道也。故大通利貞，乃得无咎也。爲隨而今大通利貞，得於時也。得時則天下隨之矣。隨之所施，唯在於時也。時異而不隨，否之道也。故隨時之義大矣哉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.129","text":"《象》曰：澤中有雷，隨；君子以嚮晦入宴息。澤中有雷，動說之象也。物皆說隨，可以无爲，不勞明鑒，故君子嚮晦入宴息也。初九，官有渝，貞吉，出門交有功。居隨之始，上无其應，无所偏係。動能隨時，意无所主者也。隨不以欲，以欲隨宜者也。故官有渝變，隨不失正也。出門无違，何所失哉。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.130","text":"《象》曰：“官有渝”，從正吉也。“出門交有功”，不失也。六二，係小子，失丈夫。隂之爲物，以處隨丗，不能獨立，必有係也。居隨之時，體於柔弱，而以乗夫剛動，豈能秉志，違於所近，隨此失彼，弗能兼與。五處己上，初處己下，故曰係小子，失丈夫也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.131","text":"《象》曰：係小子，弗兼與也。六三，係丈夫，失小子。隨有求得，利居貞。隂之爲物，以處隨丗，不能獨立，必有係也。雖體下卦，二巳據初，將何所附？故舎初係四，志在丈夫，四俱无應，亦欲於己隨之，則得其所求矣，故曰隨有求得也。應非其正，以係於人，何可以妄，故利居貞也。初處己下，四處己上，故曰係丈夫，失小子也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.132","text":"《象》曰：“係丈夫”，志舎下也。下謂初也。九四，隨有獲，貞凶。有孚在道，以明，何咎！處說之初，下據二隂，三求係已，不距則獲，故曰隨有獲也。居於臣地，履非其位，以擅其民，失於臣道，違正者也，故曰貞凶。體剛居說，而得民心，能幹其事，而成其功。者也。雖違常義，志在濟物，心存公誠，著信在道，以明其功，何咎之有？","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.133","text":"象曰：“隨有獲”，其義凶也；“有孚在道”，明功也。九五，孚于嘉，吉。履正居中，而處隨丗，盡隨時之宜，得物之誠，故嘉吉也。《象》曰：“孚于嘉吉”，位正中也。上六，拘係之，乃從，維之，王用亨于西山。隨之爲體，隂，順陽者也。最處上極，不從者也。隨道巳成，而特不從，故拘係之乃從也。率土之濵，莫非王臣，而爲不從，王之所討也，故維之，王用亨于西山也。兊爲西方，山者，塗之險隔也。處西方而爲不從，故王用通于西山。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.134","text":"《象》曰：“拘係之”，上窮也。處于上極，故窮也。䷑巽下，艮上。蠱，元亨，利渉大川。先甲三日，後甲三日。《彖》曰：蠱，剛上而柔下，上剛可以斷制，下柔可以施令。巽而止蠱。旣巽又止，不競爭也。有事而无競爭之患，故可以有爲也。蠱，元亨而天下治也。有爲而大亨，非天下治而何也？“利渉大川，往有事也”。先甲三日，後甲三日，終則有始，天行也。蠱者，有事而待能之時也。可以有爲，其在此時矣。物巳說隨，則待夫作制以定其事也。進德脩業，往則亨矣，故元亨，利渉大川也。甲者，創制之令也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.135","text":"創制不可責之以舊，故先之三日，後之三日，使令洽而後乃誅也。因事申令，終則復始，若天之行，用四時也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.136","text":"《象》曰：山下有風，蠱，君子以振民育德。蠱者，有事而待能之時也，故君子以濟民養德也。初六，幹父之蠱，有子，考无咎，厲終吉。處事之首，始見任者也。以柔巽之質，幹父之事，能承先軌，堪其任者也，故曰有子也。任爲事首，能堪其事，考乃无咎也，故曰有子，考无咎也。當事之首，是以危也。能堪其事，故終吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.137","text":"《象》曰：“幹父之蠱”，意承考也。幹事之首，時有損益，不可盡承，故意承而已。九二，幹母之蠱，不可貞。居於内中，冝幹母事，故曰幹母之蠱也。婦人之性，難可全正，冝屈巳剛，旣幹且順，故曰不可貞也。幹不失中，得中道也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.138","text":"《象》曰：“幹母之蠱”，得中道也。九三，幹父之蠱，小有悔，无大咎。以剛幹事，而无其應，故有悔也。履得其位，以正幹父，雖小有悔，終无大咎。《象》曰：“幹父之蠱”，終无咎也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.139","text":"六四，𥙿父之蠱，往見吝。體柔當位，幹不以剛，而以柔和，能𥙿先事者也。然无其應，往必不合，故曰往見吝。《象》曰：“裕父之蠱”，往未得也。六五，幹父之蠱，用譽。以柔處尊，用中而應，承先以斯，用譽之道也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.140","text":"《象》曰：“幹父用譽”，承以德也。以柔處中，不任威力也。上九，不事王侯，髙尚其事。最處事上，而不累於位，不事王侯，髙尚其事也。《象》曰：不事王侯，志可則也。䷒兊下，坤上。臨，元亨，利貞，至于八月有凶。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.141","text":"《彖》曰：臨，剛浸而長，說而順，剛中而應，大亨以正。天之道也。陽轉進長，隂道日消，君子日長，小人日憂，大亨以正之義。“至于八月有凶”，消不乆也。八月陽衰而隂長，小人道長，君子道消也，故曰有凶。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.142","text":"《象》曰：澤上有地，臨。君子以敎思无窮，容保民无疆。相臨之道，莫若說順也。不恃威制，得物之誠，故物无違也。是以君子敎思无窮，容保民无疆也。初九，咸臨，貞吉。咸，感也。感，應也。有應於四，感以臨者也。四，履正位而已。應焉，志行正者也。以剛感順，志行其正，以斯臨物，正而獲吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.143","text":"《象》曰：“咸臨貞吉”，志行正也。九二，咸臨，吉无不利。有應在五，感以臨者也。剛勝則柔危，而五體柔，非能同斯志者也。若順於五，則剛德不長，何由得吉，无不利乎？全與相違，則失於感應，其得咸臨吉无不利，必未順命也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.144","text":"《象》曰：咸臨，吉无不利，未順命也。六三，甘臨，无攸利；旣憂之，无咎。甘者，佞邪說媚，不正之名也。履非其位，居剛長之丗，而以邪說臨物，宜其无攸利也。若能盡憂其危，改脩其道，剛不害王，故咎不長。《象》曰：“甘臨”，位不當也。“旣憂之”，咎不長也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.145","text":"六四，至臨，无咎。處順應陽，不忌剛長，而乃應之，履得其位，盡其至者也。剛勝則柔危，柔不失正，則得无咎也。《象》曰：“至臨无咎”，位當也。六五，知臨，大君之宜，吉。處於尊位，履得其中，能納剛以禮，用違其正，不忌剛長，而能任之，委物以能，而不犯焉，則聦明者竭其視聽，知力者盡其謀能，不爲而成，不行而至矣。大君之宜，如此而已，故曰知臨，大君之宜，吉也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.146","text":"《象》曰：大君之宜，行中之謂也。上六，敦臨，吉，无咎。處坤之極，以敦而臨者也。志在助賢，以敦爲德，雖在剛長，剛不害厚，故无咎也。《象》曰：“敦臨之吉”，志在内也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.147","text":"䷓坤下，巽上。觀，盥而不薦，有孚顒若。王道之可觀者，莫盛乎宗廟。宗廟之可觀者，莫盛於盥也。至薦簡略，不足復觀，故觀盥而不觀薦也。孔子曰：禘自旣灌而往者，吾不欲觀之矣。盡夫觀盛，則下觀而化矣。故觀至盥，則有孚顒若也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.148","text":"《彖》曰：大觀在上，下賤而上貴也。順而巽，中正以觀天下。“觀，盥而不薦，有孚顒若”，下觀而化也。觀天之神道，而四時不忒，聖人以神道設敎，而天下服矣。統說觀之爲道，不以刑制使物，而以觀感化物者也。神則无形者也，不見天之使四時，而四時不忒；不見聖人使百姓，而百姓自服也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.149","text":"《象》曰：風行地上，觀，先王以省方觀民設敎。初六，童觀，小人无咎，君子吝。處於觀時，而最逺朝美，體於隂柔，不能自進，无所鑒見，故曰童觀。趣順而巳，无所能爲，小人之道也，故曰小人无咎。君子處大觀之時，而爲童觀，不亦鄙乎。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.150","text":"《象》曰：初六“童觀”，小人道也。六二，闚觀，利女貞。處在於内，寡所鑒見，體於柔弱，從順而巳，猶有應焉，不爲全蒙，所見者狹，故曰闚觀。居内得位，柔順寡見，故曰利女貞，婦人之道也。處大觀之時，居中得位，不能大觀廣鑒，闚觀而已，誠可醜也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.151","text":"《象》曰：“闚觀女貞”，亦可醜也。六三，觀我生，進退。居下體之極，處二卦之際，近不比尊，逺不童觀，觀風者也。居此時也，可以觀我生，進退也。《象》曰：“觀我生進退”，未失道也。處進退之時，以觀進退之幾，未失道也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.152","text":"六四，觀國之光，利用賔于王。居觀之時，最近至尊，觀國之光者也。居近得位，明習國儀者也，故曰利用賔于王也。《象》曰：“觀國之光”，尚賔也。九五：觀我生，君子无咎。居於尊位，爲觀之主，宣弘大化，光于四表，觀之極者也。上之化下，猶風之靡草，故觀民之俗，以察已道。百姓有罪，在予一人，君子風著，已乃无咎。上爲化主，將欲自觀，乃觀民也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.153","text":"《象》曰：“觀我生”，觀民也。上九，觀其生，君子无咎。觀我生，自觀其道者也；觀其生，爲民所觀者也。不在於位，最處上極，高尚其志，爲天下所觀者也。處天下所觀之地，可不愼乎？故君子德見，乃得无咎。生，猶動出也。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"},{"segId":"zhouyi@ext.c.154","text":"《象》曰：“觀其生”，志未平也。特處異地，爲衆所觀，不爲平易，和光流通，志未平也。周易卷第二。經二千四十七字，注四千七十四字。","chapter":"全卷","book":"周易（周易注·王弼本）","canonicalId":"zhouyi@ext.public","author":"王弼注、韩康伯补注","edition":"识典古籍·四部丛刊景上海涵芬楼藏宋刊本","confidenceLevel":"A","license":"公有领域"}];
